//! The guest struct layouts in `src/graphics/layout.rs` against the m68k compiler's: `tests/guest/gfx_offsets.txt` is
//! generated by `tests/guest/gfx_offsets.sh` (m68k-linux-gnu-gcc -m68020 -mno-align-int over the AROS field lists).
//! A constant that drifts from the compiler's number fails here; so does a table row with no constant (negative control
//! below proves the comparison can fail).
use amiga68k_engine::graphics::layout as l;

const TABLE: &str = include_str!("guest/gfx_offsets.txt");

fn expected() -> Vec<(&'static str, u32)> {
    TABLE.lines().filter(|x| !x.trim().is_empty()).map(|x| { let mut p = x.split_whitespace(); (p.next().unwrap(), p.next().unwrap().parse().unwrap()) }).collect()
}

