#[test]
fn every_layout_constant_equals_the_compilers_offset() {
    let ours = ours();
    for (name, v) in expected() {
        match ours.iter().find(|(n, _)| *n == name) {
            Some((_, mine)) => assert_eq!(*mine, v, "{name}: layout.rs says {mine}, m68k gcc says {v}"),
            None => panic!("{name} = {v} is in gfx_offsets.txt but has no constant in layout.rs"),
        }
    }
}

#[test]
fn the_comparison_can_fail() {
    let mut ours = ours();
    ours[0].1 += 1;
    let first = expected()[0];
    assert_ne!(ours.iter().find(|(n, _)| *n == first.0).unwrap().1, first.1, "negative control: a drifted constant differs");
}
